Fetch YouTube docs and grep key phrases — cd multicode/.cache && mkdir -p factcheck && cd factcheck && curl -sL https://developers.google.com/youtube/v3/docs/videos/insert -o ins.html; python3 -I -c "
import re,html,sys
t=open('ins.html',encoding='utf8').read()
t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t)
for k in ['unverified','Video Uploads','100 calls','audit']:
  for m in re.finditer(k,t): print(k,'::',' '.join(t[max(0,m.start()-300):m.start()+300].split()));print('---')
"; curl -sL https://developers.google.com/youtube/v3/revision_history -o rh.html; python3 -I -c "
import re,html
t=open('rh.html',encoding='utf8').read()
t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t)
for k in ['Video Uploads','unverified','granular']:
  for m in re.finditer(k,t): print(k,'::',' '.join(t[max(0,m.start()-400):m.start()+400].split()));print('---')
"

Grep revision history for synthetic media and private rules — cd multicode/.cache/factcheck && python3 -I -c "
import re,html
t=open('rh.html',encoding='utf8').read()
t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t);t=' '.join(t.split())
for k in ['containsSyntheticMedia','private viewing','locked as private','Shorts']:
  for m in re.finditer(k,t): print(k,'::',t[max(0,m.start()-250):m.start()+250]);print('---')
" | head -60
curl -sL https://developers.google.com/youtube/v3/determine_quota_cost | python3 -I -c "
import sys,re,html
t=sys.stdin.read();t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t);t=' '.join(t.split())
for k in ['Video Uploads','videos.insert','10,000']:
  for m in re.finditer(k,t): print(k,'::',t[max(0,m.start()-200):m.start()+250]);print('---')
" | head -30

Grep TikTok inbox upload limits — cd multicode/.cache/factcheck && for u in https://developers.tiktok.com/doc/content-posting-api​-reference-upload-video https://developers.tiktok.com/doc/content-posting-api-media-transfer-guide; do curl -sL -A "Mozilla/5.0" "$u" | python3 -I -c "
import sys,re,html
t=sys.stdin.read();t=re.sub(r'<script.*?</script>',' ',t,flags=re.S);t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t);t=' '.join(t.split())
for k in ['pending','unaudited','24 hours','per minute','6 requests']:
  for m in list(re.finditer(k,t))[:2]: print(k,'::',t[max(0,m.start()-200):m.start()+250]);print('---')
"; echo "==== $u"; done

Grep Instagram media reference for Reels specs — cd multicode/.cache/factcheck && curl -sL -A "Mozilla/5.0" https://developers.facebook.com/docs/instagram-platform/instagram-graph-api/reference/ig-user/media | python3 -I -c "
import sys,re,html
t=sys.stdin.read();t=re.sub(r'<script.*?</script>',' ',t,flags=re.S);t=re.sub(r'<[^>]+>',' ',t);t=html.unescape(t);t=' '.join(t.split())
for k in ['Reels Specifications','15 minutes','300MB','share_to_feed','audio_name']:
  for m in list(re.finditer(k,t))[:1]: print(k,'::',t[max(0,m.start()-100):m.start()+600]);print('---')
"

Grep YouTube docs for unverified private mode and quota changes — curl -sL https://developers.google.com/youtube/v3/docs/videos/insert | python3 -I -c "import sys,re,html;t=re.sub(r'<[^>]+>',' ',sys.stdin.read());t=html.unescape(re.sub(r'\s+',' ',t))
for k in ['unverified','private viewing','quota cost','2020']:
  for m in re.finditer(k,t): print(k,'::',t[max(0,m.start()-250):m.start()+250]);print()" | head -40; curl -sL https://developers.google.com/youtube/v3/revision_history | python3 -I -c "import sys,re,html;t=re.sub(r'<[^>]+>',' ',sys.stdin.read());t=html.unescape(re.sub(r'\s+',' ',t))
for m in re.finditer('(?i)videos.insert',t[:60000]): print(t[max(0,m.start()-300):m.start()+300]);print('==')" | head -40

Find when YouTube lifted private restriction — curl -sL https://developers.google.com/youtube/v3/revision_history | python3 -I -c "import sys,re,html;t=re.sub(r'<[^>]+>',' ',sys.stdin.read());t=html.unescape(re.sub(r'\s+',' ',t))
for k in ['not restricted','private viewing','1600','100 units']:
  for m in re.finditer(k,t): print(k,'::',t[max(0,m.start()-500):m.start()+200]);print('==')" | head -30

